class InterpListener extends ApplicationAdapter {
    String configPath, outputPath;
    Interpolation curve;
    double start, end;
    int samples;
    int tickCount = 0;
    float[] results;
    Throwable error;

    create() {
        try {
            Properties props = new Properties();
            props.load(new InputStreamReader(Gdx.files.absolute(configPath).read(), StandardCharsets.UTF_8));
            String curveName = props.getProperty("curve");
            start = Double.parseDouble(props.getProperty("start"));
            end = Double.parseDouble(props.getProperty("end"));
            samples = Integer.parseInt(props.getProperty("samples"));
            // lookup curve
            curve = lookupCurve(curveName); // via reflection on Interpolation class
            if (curve == null) throw new IllegalArgumentException("Unknown curve: " + curveName);
            results = new float[samples];
        } catch (Throwable t) {
            error = t;
            Gdx.app.exit();
        }
    }

    render() {
        if (error != null) return;
        if (tickCount >= samples) return; // shouldn't happen
        int i = tickCount;
        float t;
        if (i == samples - 1) t = 1.0f;
        else t = i / (float)(samples - 1);
        results[i] = curve.apply((float)start, (float)end, t);
        tickCount++;
        if (tickCount == samples) {
            Gdx.app.exit();
        }
    }

    dispose() {
        if (error != null) return; // don't write
        // write output file
        ...
    }
}
```

